// swift-tools-version: 6.2
//
// Morse Runner — native Swift port of VE3NEA's Morse Runner v1.68.
// The engine lives in this package (testable with `swift test`); the
// AppKit application is generated by xcodegen from project.yml and links
// these libraries.

import PackageDescription

/// Applied to every target: Swift 6 mode is the default for tools 6.x;
/// these upcoming features tighten the source rules further.
let strict: [SwiftSetting] = [
    .enableUpcomingFeature("ExistentialAny"),
    .enableUpcomingFeature("MemberImportVisibility"),
]

let package = Package(
    name: "MorseRunner",
    platforms: [.macOS(.v15)],
    products: [
        .library(name: "MorseRunnerKit",
                 targets: ["MRCore", "MRDSP", "MRScoring", "MRSimulation",
                           "MRAudio", "MRPersistence", "MRAppCore"]),
    ],
    targets: [
        // Constants, Delphi-compatible rounding, MT19937 random source,
        // WAV writer, logging.
        .target(name: "MRCore"),
        // Keyer, filters, modulator, AGC, QSB.
        .target(name: "MRDSP", dependencies: ["MRCore"]),
        // Prefix extraction, HST points, CRC32, QSO log.
        .target(name: "MRScoring", dependencies: ["MRCore", "MRDSP"]),
        // Contest, stations, DX operator state machine, callsign database.
        .target(name: "MRSimulation", dependencies: ["MRCore", "MRDSP", "MRScoring"]),
        // Real-time output (AVAudioSourceNode), SPSC ring, simulation thread.
        .target(name: "MRAudio", dependencies: ["MRCore", "MRSimulation"]),
        // UserDefaults-backed settings.
        .target(name: "MRPersistence", dependencies: ["MRCore"]),
        // UI-independent application logic (Foundation only): operating
        // keys, Run rules, captions, score files. The AppKit app applies it.
        .target(name: "MRAppCore", dependencies: ["MRCore", "MRScoring", "MRSimulation"]),

        // Reference data dumped from the C++ implementation
        // (tools/golden); the Swift port must reproduce it.
        .target(name: "MRTestSupport", dependencies: ["MRCore"],
                resources: [.copy("Fixtures")]),

        .testTarget(name: "MRCoreTests", dependencies: ["MRCore", "MRTestSupport"]),
        .testTarget(name: "MRDSPTests", dependencies: ["MRDSP", "MRTestSupport"]),
        .testTarget(name: "MRScoringTests", dependencies: ["MRScoring", "MRTestSupport"]),
        .testTarget(name: "MRSimulationTests",
                    dependencies: ["MRSimulation", "MRTestSupport"]),
        .testTarget(name: "MRAudioTests", dependencies: ["MRAudio", "MRTestSupport"]),
        .testTarget(name: "MRPersistenceTests",
                    dependencies: ["MRPersistence", "MRTestSupport"]),
        .testTarget(name: "MRAppCoreTests",
                    dependencies: ["MRAppCore", "MRSimulation", "MRScoring"]),
    ]
)

for target in package.targets {
    target.swiftSettings = (target.swiftSettings ?? []) + strict
}
